// Asteroid Dodge game implementation
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  const ship = {
    width: 40,
    height: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 40,
    speed: 5,
    color: '#7df9ff',
  };

  const keys = { left: false, right: false };
  window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = true;
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = true;
  });
  window.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = false;
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = false;
  });

  const asteroids = [];
  let asteroidTimer = 0;
  let asteroidInterval = 90; // frames
  let speedMultiplier = 1;
  let score = 0;
  let gameOver = false;

  function spawnAsteroid() {
    const size = Math.random() * 20 + 15; // radius 15-35
    const x = Math.random() * (canvas.width - size * 2) + size;
    asteroids.push({ x, y: -size, radius: size, speed: 2 * speedMultiplier });
  }

  function update() {
    if (gameOver) return;
    // move ship
    if (keys.left) ship.x = Math.max(0, ship.x - ship.speed);
    if (keys.right) ship.x = Math.min(canvas.width - ship.width, ship.x + ship.speed);

    // spawn asteroids
    if (asteroidTimer <= 0) {
      spawnAsteroid();
      asteroidTimer = asteroidInterval;
    } else {
      asteroidTimer--;
    }

    // update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // remove off-screen
      if (a.y - a.radius > canvas.height) {
        asteroids.splice(i, 1);
        score++;
        // increase difficulty gradually
        if (score % 10 === 0) speedMultiplier += 0.2;
        continue;
      }
      // collision detection (simple AABB vs circle)
      const shipRect = { x: ship.x, y: ship.y, w: ship.width, h: ship.height };
      const distX = Math.abs(a.x - (shipRect.x + shipRect.w / 2));
      const distY = Math.abs(a.y - (shipRect.y + shipRect.h / 2));
      if (distX > shipRect.w / 2 + a.radius || distY > shipRect.h / 2 + a.radius) {
        // no collision
      } else {
        // collision
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // draw ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.width, ship.height);
    // draw asteroids
    ctx.fillStyle = '#ff6b6b';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw score
    ctx.fillStyle = '#e6e6f0';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`,
      10,
      20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff6b6b';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // start game
  requestAnimationFrame(loop);
})();
